// Eine Zeile je Lauf, jeder Aufruf aktualisiert sie
const rein = $input.first().json;
const u = rein.umschlag || {};
const lauf = u.lauf || {};
// Seit 22.10.2026 (P4): Läufe des Prüfstands BC3-83 schreiben keine Zeile in laeufe
if (lauf.pruefstand === true) return [{ json: { _pruefstand: true } }];
if (!lauf.lauf_nr) throw new Error('Keine Laufnummer im Umschlag (lauf.lauf_nr)');

if (!rein.status) throw new Error('Kein Status übergeben (status)');
const status = rein.status;
// Endwerte wie in der Prüfregel der Tabelle (laeufe_status_check)
const ende = ['abgebrochen', 'freigegeben', 'nachbessern', 'abgelehnt'].includes(status);
const letzter = (u.protokoll || []).slice(-1)[0] || {};
const dateien = u.lieferung?.dateien || [];
const tickets = dateien.find(d => d._datei === 'tickets');
const epics = tickets?.epics || [];
// Kennungen der Kette (A6), erst ab BC3-10 im Umschlag
const ids = u.ids || {};

return [{
  json: {
    lauf_id: lauf.lauf_nr,
    gestartet_am: lauf.gestartet_am || null,
    beendet_am: ende ? new Date().toISOString() : null,
    modus: lauf.liefermodus || null,
    quelle: u.quelle?.art || null,
    konzept_pfad: lauf.pfad || null,
    use_case: u.lieferung?.projekt_kurzname || null,
    company_id: ids.company_id || null,
    paket_id: ids.paket_id || null,
    priorisierung_id: ids.priorisierung_id || null,
    process_id: u.konzept?.kp_id || null,
    sub_process_id: (u.konzept?.teilprozess_ids || []).join(', ') || null,
    schema_version: u.konzept?.schema_version || null,
    status,
    letzter_schritt: rein.schritt || null,
    naechster_schritt: rein.naechster || null,
    abbruch_stufe: status === 'abgebrochen' ? (rein.schritt || null) : null,
    abbruch_ursache: status === 'abgebrochen' ? (rein.ursache || (letzter.befunde || []).join(' | ') || null) : null,
    lieferung_id: u.lieferung?.lieferung_id || null,
    anzahl_epics: tickets ? epics.length : null,
    anzahl_stories: tickets ? epics.reduce((n, e) => n + (e.stories || []).length, 0) : null,
    artefakte: dateien.map(d => `${d._datei}.${d._endung || 'json'}`).join(', ') || null,
    befunde: (letzter.befunde || []).join(' | ') || null,
  },
}];

// Umschlag unverändert zurück, damit der Aufrufer nichts verliert
const rein = $('Aufgerufen').first().json;
return [{ json: { lauf_id: rein.lauf_id, umschlag: rein.umschlag } }];
